import{_ as a,o as t,c as r,a4 as s}from"./chunks/framework.BRzJ4ijD.js";const h=JSON.parse('{"title":"Snowflake 数仓","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/case/snowflake.md","filePath":"system-design/case/snowflake.md","lastUpdated":1788475713000}'),i={name:"system-design/case/snowflake.md"};function o(n,e,l,c,u,d){return t(),r("div",null,[...e[0]||(e[0]=[s(`<h1 id="snowflake-数仓" tabindex="-1">Snowflake 数仓 <a class="header-anchor" href="#snowflake-数仓" aria-label="Permalink to &quot;Snowflake 数仓&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p><strong>Snowflake</strong> (2012 founded, 2020 IPO = &quot;BIGTIME revenue growth&quot; story) 重新定义了 cloud data warehouse 即 架构——<strong>shared-data architecture</strong>: storage (S3 / Blob) separated from compute (virtual warehouses), 每个算力弹性 增长 / 缩小秒级。 传统 on-prem Teradata/Hive 是 shared-nothing 计算+本地盘, 扩展弱。 Snowflake 强调 self-tuning, zero-copy clone, Time Travel, data sharing, seamless scale-out 并发 也 可以。 本章梳理 Snowflake architecture, storage internal (micro-partitions + hybrid columnar), services 层, 查询优化, 与 BigQuery / Redshift 对比, 典型 use (ETL, BI, ad-hoc analytics) 与事故 (clone cost 爆炸)。</p><hr><h2 id="一、architecture-three-tier-shared-data" tabindex="-1">一、Architecture (Three-tier Shared-Data) <a class="header-anchor" href="#一、architecture-three-tier-shared-data" aria-label="Permalink to &quot;一、Architecture (Three-tier Shared-Data)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────┐</span></span>
<span class="line"><span>│   Cloud Services Layer          │</span></span>
<span class="line"><span>│ (metadata, auth, optimizer,    │</span></span>
<span class="line"><span>│  query compiler, security)      │</span></span>
<span class="line"><span>└─────────────────────────────────┘</span></span>
<span class="line"><span>         |              |</span></span>
<span class="line"><span>┌─────────────────────────────────┐</span></span>
<span class="line"><span>│   Query Processing Layer        │</span></span>
<span class="line"><span>│ (Virtual Warehouses: elastic   │</span></span>
<span class="line"><span>│  compute clusters MPP)         │</span></span>
<span class="line"><span>└─────────────────────────────────┘</span></span>
<span class="line"><span>         |</span></span>
<span class="line"><span>┌─────────────────────────────────┐</span></span>
<span class="line"><span>│   Storage Layer (Cloud Object)  │</span></span>
<span class="line"><span>│ (S3/Azure Blob/GCS)            │</span></span>
<span class="line"><span>│ micro-partitions +     				 |</span></span>
<span class="line"><span>│ hybrid-columnar compressed     │</span></span>
<span class="line"><span>└─────────────────────────────────┘</span></span></code></pre></div><h3 id="cloud-services" tabindex="-1">Cloud Services <a class="header-anchor" href="#cloud-services" aria-label="Permalink to &quot;Cloud Services&quot;">​</a></h3><ul><li>Metadata management (catalog)，access control(RBAC), query optimizer, 管理 virtual warehouses</li><li><strong>Always-on, 多租户</strong>, 但 不 query 处理 (无 算力)</li></ul><h3 id="query-processing" tabindex="-1">Query Processing <a class="header-anchor" href="#query-processing" aria-label="Permalink to &quot;Query Processing&quot;">​</a></h3><ul><li>Virtual Warehouses (VW): user-provisioned independent compute clusters (size: XS~6X-Large)</li><li>每个 VW run 在 provisioned cluster, elastic auto-suspend/resume within seconds (warehouse&#39;s empty usage 挂 停).</li><li>多 VW 并行 isolation (ETL loading VW 与 用户 BI VW 独立 cluster), 不 concurrency 竞争。</li></ul><h3 id="storage" tabindex="-1">Storage <a class="header-anchor" href="#storage" aria-label="Permalink to &quot;Storage&quot;">​</a></h3><ul><li>All data in cloud object (S3) as <strong>micro-partitions</strong>: compressed, columnar, immutable blocks (~50-500MB compressed).</li><li>Micro-partition metadata (min/max per column, bloom filter by zone maps, stretch) in service layer.</li><li>Columnar, compressed (自动选择 compression algorithm Zstandard/gzip etc).</li><li><strong>Time Travel &amp; Fail-safe</strong>: at any point recover table state prior with up to 90-day retention。</li></ul><hr><h2 id="二、micro-partition-internal" tabindex="-1">二、Micro-Partition Internal <a class="header-anchor" href="#二、micro-partition-internal" aria-label="Permalink to &quot;二、Micro-Partition Internal&quot;">​</a></h2><ul><li>每 table data 分 immutable micro-partitions; auto clustered by natural order.</li><li>Per micro-partition: min/max per column, bloom filter null count etc. metadata 存在 cloud services.</li><li>Query 扫描的时候, prune 不需要 scan micro-partition &gt; 用 metadata 知 不需要 读 =&gt; significantly less I/O.</li></ul><h3 id="hybrid-columnar-partition" tabindex="-1">Hybrid Columnar + Partition <a class="header-anchor" href="#hybrid-columnar-partition" aria-label="Permalink to &quot;Hybrid Columnar + Partition&quot;">​</a></h3><p>Stored as columnar 用 PAX (Partition attributes across): each micro-partition 是 PAX layout within block (columnar inside partition). Cross-partition query stitch columns for needed rows.</p><h3 id="zero-copy-clone" tabindex="-1">Zero-Copy Clone <a class="header-anchor" href="#zero-copy-clone" aria-label="Permalink to &quot;Zero-Copy Clone&quot;">​</a></h3><p>Clone table instantly without data copy: copy metadata entries pointing to same micro-partitions; only later data modification trigger new micro-partitions (Copy on Write). 秒级 零成本 test env.</p><h3 id="time-travel" tabindex="-1">Time Travel <a class="header-anchor" href="#time-travel" aria-label="Permalink to &quot;Time Travel&quot;">​</a></h3><p>Restore table at past state up to 1-90 days (according edition). Data not deleted at drop (micro-partition kept with retention). Similar time travel retention changes for GDPR data erasure.</p><hr><h2 id="三、virtual-warehouses-multi-cluster" tabindex="-1">三、Virtual Warehouses Multi-Cluster <a class="header-anchor" href="#三、virtual-warehouses-multi-cluster" aria-label="Permalink to &quot;三、Virtual Warehouses Multi-Cluster&quot;">​</a></h2><ul><li>Cluster count = &quot;maximum concurrency concurrency is dynamic cluster auto-scale&quot;. User query concurrent set lock in mult处理 (compute for big cluster).</li><li>Auto-suspend after N min idle → cost savings (cloud money).</li><li>Multi-cluster warehouse ~concurrent heavy BI.</li></ul><h3 id="auto-scaling" tabindex="-1">Auto-Scaling <a class="header-anchor" href="#auto-scaling" aria-label="Permalink to &quot;Auto-Scaling&quot;">​</a></h3><p>Load queue ~decide VW instance check; spin up &#39;added cluster to reduce queue depth&#39;. Max cluster = 10 (default).</p><h3 id="resource-monitors-budgets" tabindex="-1">Resource monitors &amp; Budgets <a class="header-anchor" href="#resource-monitors-budgets" aria-label="Permalink to &quot;Resource monitors &amp; Budgets&quot;">​</a></h3><p>Set monthly credit budget per VW to block runaway cost.</p><h3 id="data-sharing" tabindex="-1">Data Sharing <a class="header-anchor" href="#data-sharing" aria-label="Permalink to &quot;Data Sharing&quot;">​</a></h3><ul><li>Share data cross accounts with read-only views; zero copy of actual data (point to same micro-partitions).</li><li>Enables &quot;publisher / subscriber&quot; model; live data sharing 内部 and external.</li></ul><hr><h2 id="四、query-optimizer-cbo" tabindex="-1">四、Query Optimizer (CBO) <a class="header-anchor" href="#四、query-optimizer-cbo" aria-label="Permalink to &quot;四、Query Optimizer (CBO)&quot;">​</a></h2><h3 id="snowflake-优化器" tabindex="-1">Snowflake 优化器 <a class="header-anchor" href="#snowflake-优化器" aria-label="Permalink to &quot;Snowflake 优化器&quot;">​</a></h3><ul><li>Cost-based optimizer (CBO) use statistic on micro-partition (per column distribution, histogram).</li><li>Automatic clustering: see heavy query and create clustering key which 聚簇 微 分区 好 prune; no user DBA 手 index.</li><li>Search space for join order: stats derived from micro-partitions 让 内存 估算 大数据 join 量 成本。</li></ul><h3 id="query-acceleration-service" tabindex="-1">Query Acceleration Service <a class="header-anchor" href="#query-acceleration-service" aria-label="Permalink to &quot;Query Acceleration Service&quot;">​</a></h3><p>Cloud service external run queries in <strong>Serverless Compute</strong> when VWS are cold or stopped: 5-10s latency fast start.</p><hr><h2 id="五、比较-snowflake-vs-bigquery-vs-redshift" tabindex="-1">五、比较: Snowflake vs BigQuery vs Redshift <a class="header-anchor" href="#五、比较-snowflake-vs-bigquery-vs-redshift" aria-label="Permalink to &quot;五、比较: Snowflake vs BigQuery vs Redshift&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>Snowflake</th><th>BigQuery</th><th>Redshift Spectrum</th></tr></thead><tbody><tr><td>架构</td><td>shared-data multi-cluster</td><td>full serverless distributed Dremel</td><td>shared-nothing clustered (RA3 nodes)</td></tr><tr><td>Storage</td><td>cloud object (S3, Blob)</td><td>Colossus/GCS (capacity store)</td><td>S3 / local SSD for hot data</td></tr><tr><td>Compute</td><td>provisioned VW clusters elastic</td><td>serverless <strong>slots</strong> auto-scale</td><td>provisioned cluster nodes (DC2 / RA3)</td></tr><tr><td>Scaling</td><td>virtual warehouse resize (secs)</td><td>automatic (serverless)</td><td>resize cluster (minutes)</td></tr><tr><td>Concurrency</td><td>Multi-cluster warehouses 分 离</td><td>high concurrency auto</td><td>limited by cluster size queue</td></tr><tr><td>Price model</td><td>per-second credit per warehouse</td><td>on-demand per query data processed or slot reservation</td><td>per node/hour</td></tr><tr><td>SQL standard</td><td>ANSI SQL + extension</td><td>SQL:2011 + extensions</td><td>PostgreSQL-based</td></tr><tr><td>Semistructured data</td><td>VARIANT column (JSON auto-discovery)</td><td>JSON natively</td><td>Redshift Spectrum JSON parse</td></tr></tbody></table><p>Snowflake 能 fine-grained 控制 VWS for ETL + BI isolation. BigQuery simpler auto-provision by slots. Redshift 原 形 上 更 针对 closed complex transactions + column 化 tables.</p><hr><h2 id="六、典型使用" tabindex="-1">六、典型使用 <a class="header-anchor" href="#六、典型使用" aria-label="Permalink to &quot;六、典型使用&quot;">​</a></h2><h3 id="etl-pipeline" tabindex="-1">ETL pipeline <a class="header-anchor" href="#etl-pipeline" aria-label="Permalink to &quot;ETL pipeline&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>S3 Event → Snowpipe (continuous ingest) → stage table  → transform via task + streams (CDC inside Snowflake) →  gold table</span></span>
<span class="line"><span>BI query against gold table via BI tools (Tableau, Looker).</span></span></code></pre></div><h3 id="data-sharing-marketplace" tabindex="-1">Data Sharing Marketplace <a class="header-anchor" href="#data-sharing-marketplace" aria-label="Permalink to &quot;Data Sharing Marketplace&quot;">​</a></h3><p>Publisher publish data set (e.g. COVID stats) → sub-live query across Snowflake accounts.</p><h3 id="adp-analytics-machine-learning" tabindex="-1">ADP Analytics + Machine Learning <a class="header-anchor" href="#adp-analytics-machine-learning" aria-label="Permalink to &quot;ADP Analytics + Machine Learning&quot;">​</a></h3><p>Leverage internal SQL, external functions (ML models via cloud Function URL)。</p><hr><h2 id="七、典型事故" tabindex="-1">七、典型事故 <a class="header-anchor" href="#七、典型事故" aria-label="Permalink to &quot;七、典型事故&quot;">​</a></h2><h3 id="snowflake-zero-copy-clone-dropped-cd-巨-费" tabindex="-1">Snowflake &quot;Zero-Copy Clone Dropped CD 巨 费&quot; <a class="header-anchor" href="#snowflake-zero-copy-clone-dropped-cd-巨-费" aria-label="Permalink to &quot;Snowflake &quot;Zero-Copy Clone Dropped CD 巨 费&quot;&quot;">​</a></h3><p>Clone large table (1PB) share micro-partitions; user run heavy transformation on clone but keep clone long-time. Micro-partitions 修改 分 离 copy (CoW) accumulated massive extra storage charge. Fix: drop clone promptly, monitor, use time-limited 批。</p><h3 id="virtual-warehouse-auto-suspend-off-→-🎹-单月-50k-bill" tabindex="-1">Virtual Warehouse Auto-Suspend off → 🎹 单月 $50K bill <a class="header-anchor" href="#virtual-warehouse-auto-suspend-off-→-🎹-单月-50k-bill" aria-label="Permalink to &quot;Virtual Warehouse Auto-Suspend off → 🎹 单月 $50K bill&quot;">​</a></h3><p>某 team 误 set <code>AUTO_SUSPEND=0</code> on 4XL VW. Not used 3 weeks but ran continuous billed = ~$50K extra. Fix: always enable auto-suspend = 60s (default 10 min).</p><h3 id="snowpipe-输入-burst-backlog" tabindex="-1">Snowpipe 输入 burst -&gt; backlog <a class="header-anchor" href="#snowpipe-输入-burst-backlog" aria-label="Permalink to &quot;Snowpipe 输入 burst -&gt; backlog&quot;">​</a></h3><p>High continuous file load via Snowpipe, which queue 累积 → large delay up 30 min for data to be visible. Fix: larger warehouse for COPY inline + Snowpipe increased pipe count.</p><h3 id="multi-cluster-warehouse-burst-not-activated" tabindex="-1">Multi-Cluster Warehouse Burst not Activated <a class="header-anchor" href="#multi-cluster-warehouse-burst-not-activated" aria-label="Permalink to &quot;Multi-Cluster Warehouse Burst not Activated&quot;">​</a></h3><p>Concurrency 高, but VW <code>MAX_CLUSTER_COUNT=1</code> — cannot auto-scale beyond 1. Some queries queued 15 sec. Fix: set <code>MAX_CLUSTER=5</code> multi-cluster.</p><hr><h2 id="八、易错清单" tabindex="-1">八、易错清单 <a class="header-anchor" href="#八、易错清单" aria-label="Permalink to &quot;八、易错清单&quot;">​</a></h2><ol><li><strong>AUTO_SUSPEND 必设 (data warehouse 不是 always-on service)</strong>: default 10 min, budget-safe.</li><li><strong>Clone 共享 micro-partitions + 改 事 become separation</strong>: 大量 改 增 storage cost.</li><li><strong>Time-travel data 超过 retention, fail-safe = still 保障</strong>: bill retention (0-7 days enterprise). Know GDPR 清除.</li><li><strong>Multi-cluster warehouse 必须 配 MAX_CLUSTER_COUNT &gt; 1</strong>: other 定 async with long queue.</li><li><strong>Snowpipe ingest latency is 1-3 min</strong>: real-time needs streaming (Kafka + Snowpipe Streaming) 直接.</li></ol><hr><h2 id="九、这一章带走的东西" tabindex="-1">九、这一章带走的东西 <a class="header-anchor" href="#九、这一章带走的东西" aria-label="Permalink to &quot;九、这一章带走的东西&quot;">​</a></h2><ol><li>Snowflake = shared-data, 分离 Storage (Object) + Compute (virtual warehouse) + Services 三层.</li><li>Micro-partitions = PAX 存储 + metadata prune + columnar compression; zero-copy clone / time travel 用 分区。</li><li>Virtual warehouse: auto-suspend + 多集群 elastic scale, per-second billing, multi-concurrency 让 BI + ETL 隔离。</li><li>核心 trade-off: multi-cluster warehouse = compute 隔离, serverless auto-suspend reducing cost.</li><li>Semi-structured data native <code>VARIANT</code> type (JSON) parse 高效 比 Redshift Spectrum JSON 解析、 BigQuery 原生 JSON.</li><li>事故: 忘 关 auto-suspend = 数万美 monthly bill.</li></ol><hr><p>下一节 → <a href="./k8s-control-plane">Kubernetes Control Plane</a></p>`,66)])])}const m=a(i,[["render",o]]);export{h as __pageData,m as default};
